import { useEffect, useRef, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { io } from 'socket.io-client';
import Peer from 'simple-peer';
import {
  FiMic, FiMicOff, FiVideo, FiVideoOff, FiPhoneOff
} from 'react-icons/fi';
import { api } from '../../api/api';
import { useAuth } from '../../context/AuthContext';

const SOCKET_URL = 'http://localhost:5000';

export default function VideoRoom() {
  const { roomId } = useParams();
  const navigate = useNavigate();
  const { user } = useAuth();

  const [session, setSession] = useState(null);
  const [myStream, setMyStream] = useState(null);
  const [remotePeers, setRemotePeers] = useState({});
  const [error, setError] = useState('');
  const [permission, setPermission] = useState('pending');
  const [micOn, setMicOn] = useState(true);
  const [camOn, setCamOn] = useState(true);

  const myVideoRef = useRef(null);
  const socketRef = useRef(null);
  const peersRef = useRef({});

  /* 1. Verify room + load session info */
  useEffect(() => {
    api(`/classroom/rooms/${roomId}`)
      .then(setSession)
      .catch((e) => setError(e.message));
  }, [roomId]);

  /* 2. Ask for camera + mic (this triggers the browser permission prompt) */
  useEffect(() => {
    let cancelled = false;

    async function getMedia() {
      if (!navigator.mediaDevices?.getUserMedia) {
        setError('Your browser does not support camera access.');
        setPermission('denied');
        return;
      }
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: true,
          audio: true
        });
        if (cancelled) {
          stream.getTracks().forEach((t) => t.stop());
          return;
        }
        setMyStream(stream);
        setPermission('granted');
        if (myVideoRef.current) myVideoRef.current.srcObject = stream;
      } catch (err) {
        let msg = 'Could not access camera/microphone.';
        if (err.name === 'NotAllowedError') {
          msg = 'Permission was denied. Click the camera icon in your browser bar, allow access, then reload.';
        } else if (err.name === 'NotFoundError') {
          msg = 'No camera or microphone found on this device.';
        }
        setError(msg);
        setPermission('denied');
      }
    }

    getMedia();
    return () => { cancelled = true; };
  }, []);

  /* 3. Connect to Socket.IO + set up peer connections */
  useEffect(() => {
    if (!myStream || !session) return;

    const socket = io(SOCKET_URL);
    socketRef.current = socket;

    socket.on('connect', () => {
      socket.emit('join-room', {
        roomId: session.roomId,
        userId: user.id,
        name: user.name
      });
    });

    socket.on('existing-users', (users) => {
      users.forEach(({ socketId, name }) => {
        setRemotePeers((prev) => ({
          ...prev,
          [socketId]: { name, stream: null }
        }));
        const peer = createPeer(socketId, myStream, user.name);
        peersRef.current[socketId] = peer;
      });
    });

    socket.on('user-joined', ({ socketId, name }) => {
      setRemotePeers((prev) => ({
        ...prev,
        [socketId]: { name, stream: null }
      }));
    });

    socket.on('signal', ({ from, signal, name }) => {
      let peer = peersRef.current[from];
      if (!peer) {
        peer = createResponderPeer(from, signal, myStream, name);
        peersRef.current[from] = peer;
      } else {
        peer.signal(signal);
      }
    });

    socket.on('user-left', (socketId) => {
      peersRef.current[socketId]?.destroy();
      delete peersRef.current[socketId];
      setRemotePeers((prev) => {
        const copy = { ...prev };
        delete copy[socketId];
        return copy;
      });
    });

    return () => {
      socket.disconnect();
      Object.values(peersRef.current).forEach((p) => p.destroy());
      peersRef.current = {};
    };
    // eslint-disable-next-line
  }, [myStream, session]);

  /* Peer factories */
  const createPeer = (targetId, stream, myName) => {
    const peer = new Peer({ initiator: true, trickle: false, stream });

    peer.on('signal', (signal) => {
      socketRef.current.emit('signal', { to: targetId, signal, name: myName });
    });

    peer.on('stream', (remoteStream) => {
      setRemotePeers((prev) => ({
        ...prev,
        [targetId]: { ...(prev[targetId] || {}), stream: remoteStream }
      }));
    });

    peer.on('close', () => removePeer(targetId));
    peer.on('error', (e) => console.error('peer error', e));
    return peer;
  };

  const createResponderPeer = (targetId, incomingSignal, stream, name) => {
    const peer = new Peer({ initiator: false, trickle: false, stream });

    peer.on('signal', (signal) => {
      socketRef.current.emit('signal', { to: targetId, signal, name: user.name });
    });

    peer.on('stream', (remoteStream) => {
      setRemotePeers((prev) => ({
        ...prev,
        [targetId]: { name: prev[targetId]?.name || name, stream: remoteStream }
      }));
    });

    peer.on('close', () => removePeer(targetId));
    peer.on('error', (e) => console.error('peer error', e));
    peer.signal(incomingSignal);
    return peer;
  };

  const removePeer = (id) => {
    delete peersRef.current[id];
    setRemotePeers((prev) => {
      const copy = { ...prev };
      delete copy[id];
      return copy;
    });
  };

  /* Controls */
  const toggleMic = () => {
    if (!myStream) return;
    myStream.getAudioTracks().forEach((t) => (t.enabled = !micOn));
    setMicOn((v) => !v);
  };

  const toggleCam = () => {
    if (!myStream) return;
    myStream.getVideoTracks().forEach((t) => (t.enabled = !camOn));
    setCamOn((v) => !v);
  };

  const leaveRoom = () => {
    myStream?.getTracks().forEach((t) => t.stop());
    socketRef.current?.disconnect();
    Object.values(peersRef.current).forEach((p) => p.destroy());
    peersRef.current = {};
    navigate(-1);
  };

  const remoteList = Object.entries(remotePeers);

  /* Error screen */
  if (error) {
    return (
      <div className="video-room video-room--error">
        <div className="video-room__error-card">
          <h2>Cannot join the classroom</h2>
          <p>{error}</p>
          <button className="btn btn--primary" onClick={() => navigate(-1)}>
            Go back
          </button>
        </div>
      </div>
    );
  }

  /* Waiting on permission */
  if (permission === 'pending' || !session) {
    return (
      <div className="video-room video-room--loading">
        <div className="video-room__loader">
          <div className="spinner" />
          <h2>Connecting…</h2>
          <p>Please allow camera and microphone access when your browser asks.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="video-room">
      <header className="video-room__header">
        <div>
          <h2>{session.title}</h2>
          <p>{session.subject} · {session.className} · Teacher: {session.teacherName}</p>
        </div>
        <span className="pill pill--live">● LIVE · {remoteList.length + 1} in room</span>
      </header>

      <div className="video-grid">
        <div className="video-tile video-tile--local">
          <video ref={myVideoRef} autoPlay playsInline muted />
          <div className="video-tile__label">You ({user.name})</div>
          {!camOn && <div className="video-tile__off">Camera off</div>}
        </div>

        {remoteList.map(([socketId, peer]) => (
          <RemoteVideo key={socketId} name={peer.name} stream={peer.stream} />
        ))}
      </div>

      <div className="video-controls">
        <button
          className={`video-controls__btn ${micOn ? '' : 'video-controls__btn--off'}`}
          onClick={toggleMic}
          title={micOn ? 'Mute' : 'Unmute'}
        >
          {micOn ? <FiMic size={20} /> : <FiMicOff size={20} />}
        </button>

        <button
          className={`video-controls__btn ${camOn ? '' : 'video-controls__btn--off'}`}
          onClick={toggleCam}
          title={camOn ? 'Turn camera off' : 'Turn camera on'}
        >
          {camOn ? <FiVideo size={20} /> : <FiVideoOff size={20} />}
        </button>

        <button
          className="video-controls__btn video-controls__btn--end"
          onClick={leaveRoom}
          title="Leave"
        >
          <FiPhoneOff size={20} />
        </button>
      </div>
    </div>
  );
}

/* Sub-component to attach a remote MediaStream to a <video> */
function RemoteVideo({ name, stream }) {
  const ref = useRef(null);

  useEffect(() => {
    if (ref.current && stream) ref.current.srcObject = stream;
  }, [stream]);

  return (
    <div className="video-tile">
      <video ref={ref} autoPlay playsInline />
      <div className="video-tile__label">{name}</div>
      {!stream && <div className="video-tile__off">Connecting…</div>}
    </div>
  );
}
